const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const DRAFTS = STATE + '/drafts';
const PUBLISH = '/home/node/.n8n/queue/publish';
const LOG = '/home/node/.n8n/logs';
for (const d of [STATE, DRAFTS, PUBLISH, PUBLISH + '/done',
  PUBLISH + '/failed', PUBLISH + '/skipped', PUBLISH + '/processing', LOG]) {
  fs.mkdirSync(d, { recursive: true });
}
const token = ENV('TELEGRAM_BOT_TOKEN');
const tg = async (method, body) => {
  try {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + token + '/' + method,
      body: body,
      json: true
    });
  } catch (e) { return null; }
};
const log = (rec) => fs.appendFileSync(LOG + '/moderation.jsonl',
  JSON.stringify({ ts: new Date().toISOString(), ...rec }) + '\n');
// Enabled platforms come from the PUBLISH_PLATFORMS env var
// (comma-separated, e.g. "vk"; injected through docker-compose.yml) -
// the single source sp-publish's Publish Tick reads too, so the two
// gates cannot drift apart. A draft approved for a disabled platform
// just cycles queue -> skipped/ forever.
const ENABLED = {};
for (const p of String(ENV('PUBLISH_PLATFORMS') || 'vk').split(',')) {
  const k = p.trim().toLowerCase();
  if (k) ENABLED[k] = true;
}
const loadDraft = (id) => JSON.parse(fs.readFileSync(DRAFTS + '/' + id + '.json', 'utf8'));
