// leave a torn JSON behind. A corrupt DRAFTS/<id>.json must fail the
// Prepare Draft overwrite guard CLOSED - and torn files are exactly
// how 'corrupt' happens, so state writes get the same tmp+rename
// discipline the queue files already had.
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
const saveDraft = (d) => writeJsonAtomic(DRAFTS + '/' + d.id + '.json', d);
