// TELEGRAM_CHAT_ID env wins, the tg.json that sp-tg-setup writes is the
// compat fallback. The old self-heal wrote tg.json from ANY posted
// chat.id - one crafted request redirected every future draft preview
// (text + media) to a foreign chat.
const OPERATOR_CHAT = ENV('TELEGRAM_CHAT_ID') || (() => {
  try {
    return JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id;
  } catch (e) { return null; }
