// callback_query 'ap:<id>' enqueues a draft straight to the live VK
// wall. Constant-time-ish compare without crypto (only fs is allowed
// in Code nodes).
const WEBHOOK_SECRET = ENV('TG_WEBHOOK_SECRET');
const secretOk = (got) => {
  const a = String(got == null ? '' : got);
  if (!WEBHOOK_SECRET || a.length !== WEBHOOK_SECRET.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ WEBHOOK_SECRET.charCodeAt(i);
  }
  return diff === 0;
